# Kaggle kernel for Stage B (transcripts). Generated by kaggle/build_transcribe.sh from src/transcribe.py.
import base64, glob, os, subprocess, sys, time
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "faster-whisper"], check=True)
import torch
from huggingface_hub import snapshot_download

OUT = "/kaggle/working"
SCRIPT = "/tmp/transcribe.py"
open(SCRIPT, "w").write(base64.b64decode("").decode())
csv = glob.glob("/kaggle/input/**/train.csv", recursive=True)
assert csv, "competition data not attached"
DATA = os.path.dirname(csv[0])
MODEL = snapshot_download("Systran/faster-whisper-large-v3")  # MIT; downloaded once before workers start

# CTranslate2 needs cuDNN/cuBLAS; point it at the copies shipped with the pip nvidia packages.
libs = [d for pat in ("nvidia/cudnn/lib", "nvidia/cublas/lib") for d in glob.glob(f"/usr/local/lib/python3*/*-packages/{pat}")]
env = {**os.environ, "LD_LIBRARY_PATH": ":".join(libs + [os.environ.get("LD_LIBRARY_PATH", "")])}

n = max(1, torch.cuda.device_count())
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], "| libs", libs, flush=True)
args = ["--data", DATA, "--out", OUT, "--model", MODEL, "--device", "cuda", "--nshards", str(n)]
t0 = time.time()
procs = [subprocess.Popen([sys.executable, SCRIPT, *args, "--shard", str(i)],
                          env={**env, "CUDA_VISIBLE_DEVICES": str(i)}) for i in range(n)]
codes = [p.wait() for p in procs]
print("worker exit codes:", codes, "| wall time %.0f s" % (time.time() - t0), flush=True)
assert all(c == 0 for c in codes)
lines = []
for i in range(n):
    p = f"{OUT}/transcripts.s{i}.jsonl" if n > 1 else f"{OUT}/transcripts.jsonl"
    lines += open(p).read().splitlines()
    if n > 1:
        os.remove(p)
open(f"{OUT}/transcripts.jsonl", "w").write("\n".join(lines) + "\n")
print("merged transcripts:", len(lines), flush=True)
